  if (!dados.destino) pedir(['destino'],'destino','Para qual cidade vocês querem viajar?');
  if (!dados.data_ida && !dados.data_volta) pedir(['datas'],'datas válidas, com ano','Quais são as datas de ida e volta, incluindo o ano?');
  else {
    if (!dados.data_ida) pedir(['datas'],'data de ida válida, com ano','Qual é a data de ida, incluindo o ano?');
    if (!dados.data_volta) pedir(['datas'],'data de volta válida, com ano','Qual é a data de volta, incluindo o ano?');
  }
  if (dados.data_ida && dados.data_volta && dados.data_volta <= dados.data_ida)
    pedir(['datas'],'data de volta posterior à ida','A volta precisa ser depois da ida para este catálogo. Quais são as datas corretas?');
  if (!Number.isInteger(dados.adultos) || dados.adultos < 1 || dados.adultos > 20)
    pedir(['adultos'],'quantidade de adultos entre 1 e 20','Quantos adultos vão viajar? Informe um número inteiro entre 1 e 20.');
  if (!Number.isInteger(dados.criancas) || dados.criancas < 0 || dados.criancas > 20)
    pedir(['criancas'],'quantidade de crianças não confirmada','Quantas crianças vão viajar? Se não houver, informe zero ou “sem crianças”.');
  else if (dados.criancas > 0)
    pedir(['criancas'],'viagem com crianças fora do catálogo','Este catálogo cobre apenas viagens sem crianças. Para incluir crianças, será necessária uma consulta manual.');
  const semValor = !(dados.orcamento_valor > 0);
  const semTipo = !['total','por_pessoa'].includes(dados.orcamento_tipo);
  if (semValor) {
    const campos=['orcamento'];
