  const comparacao = catalogo.map(o => {
    const motivos = [];
    if (cidade(o.origem) !== cidade(item.dados.origem)) motivos.push('origem diferente');
    if (cidade(o.destino) !== cidade(item.dados.destino)) motivos.push('destino diferente');
    if (o.data_ida !== item.dados.data_ida || o.data_volta !== item.dados.data_volta) motivos.push('datas diferentes');
    if (o.adultos !== item.dados.adultos || (o.criancas || 0) !== item.dados.criancas) motivos.push('viajantes diferentes');
    if (o.moeda !== 'BRL') motivos.push('moeda diferente');
