  const semTipo = !['total','por_pessoa'].includes(dados.orcamento_tipo);
  if (semValor) {
    const campos=['orcamento'];
    let pergunta='Qual é o orçamento disponível';
    if (!dados.moeda) {campos.push('moeda'); pergunta+=' e em qual moeda';}
    pergunta+='?';
    if (semTipo) {campos.push('tipo'); pergunta+=' Informe também se o valor é total ou por pessoa.';}
    pedir(campos,'orçamento positivo e condições a confirmar',pergunta);
  } else if (semTipo)
    pedir(['tipo'],'se o orçamento é total ou por pessoa',`O orçamento de ${formatarValor(dados.orcamento_valor,dados.moeda)} é para a viagem inteira ou por pessoa?`);
  if (!dados.moeda && !semValor)
    pedir(['moeda'],'moeda do orçamento','Em qual moeda está o orçamento informado? Este catálogo usa reais (BRL).');
  else if (dados.moeda && dados.moeda !== 'BRL')
    pedir(['moeda'],'orçamento em reais (BRL)','Este catálogo usa reais (BRL). Qual é o orçamento em reais? Não fazemos conversão automática de moedas.');

  // A extração pode repetir ausências em ambiguidades. Só eliminamos repetições
  // ligadas a campos que já têm pergunta; contradições continuam bloqueando.
  const repetidas = new Set();
  for (const ambiguidade of dados.ambiguidades) {
    const a=chave(ambiguidade);
    if (repetidas.has(a)) continue;
    repetidas.add(a);
    const ausencia=/nao (?:foi |esta |foram )?(?:informad|especificad|mencionad)|ausente|nenhuma mencao|assumid/.test(a);
    const conflito=/contrad|conflit|incompativ|diferentes|diverg|duas datas/.test(a);
    const campos=[];
    if (/origem|cidade de saida/.test(a)) campos.push('origem');
    if (/destino/.test(a)) campos.push('destino');
    if (/\b(?:datas?|ida|volta)\b/.test(a)) campos.push('datas');
    if (/adult/.test(a)) campos.push('adultos');
    if (/crianc/.test(a)) campos.push('criancas');
    if (/orcamento/.test(a)) campos.push(/total|por pessoa/.test(a)?'tipo':'orcamento');
    if (/moeda/.test(a)) campos.push('moeda');
    if (ausencia && !conflito && campos.length && campos.every(c=>camposPendentes.has(c))) continue;
    pendencias.push(ambiguidade);
    perguntas.push('Preciso esclarecer este ponto: “'+ambiguidade.replace(/[.?!]+$/,'')+'”. Pode confirmar a informação correta?');
  }
  const completo = pendencias.length === 0;
  const orcamento_total = completo ? dados.orcamento_valor * (dados.orcamento_tipo === 'por_pessoa' ? dados.adultos : 1) : null;
  return {mensagem_original: texto(entrada.mensagem_original),modo:entrada.modo||'campos informados',dados,pendencias:[...new Set(pendencias)],perguntas:[...new Set(perguntas)],completo,orcamento_total};
}
function buscarOpcoes(item, catalogo) {
  if (!item.completo) throw new Error('A consulta exige dados completos e válidos.');
  if (!Array.isArray(catalogo)) throw new Error('Catálogo inválido: esperado um array.');
  const comparacao = catalogo.map(o => {
    const motivos = [];
    if (cidade(o.origem) !== cidade(item.dados.origem)) motivos.push('origem diferente');
    if (cidade(o.destino) !== cidade(item.dados.destino)) motivos.push('destino diferente');
    if (o.data_ida !== item.dados.data_ida || o.data_volta !== item.dados.data_volta) motivos.push('datas diferentes');
    if (o.adultos !== item.dados.adultos || (o.criancas || 0) !== item.dados.criancas) motivos.push('viajantes diferentes');
    if (o.moeda !== 'BRL') motivos.push('moeda diferente');
    if (!Number.isFinite(o.valor_total) || o.valor_total <= 0) motivos.push('valor inválido no catálogo');
    else if (o.valor_total > item.orcamento_total) motivos.push('acima do orçamento');
    return {...o,compativel:motivos.length===0,motivos};
  });
  return {...item,comparacao,opcoes:comparacao.filter(o=>o.compativel),catalogo_ficticio:true};
}
function moedaBR(v) { return Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}); }
function formatarValor(v,moeda) { return moeda === 'BRL' ? moedaBR(v) : Number(v).toLocaleString('pt-BR') + (moeda ? ' '+moeda : ' (moeda a confirmar)'); }
function dataBR(v) { return v ? v.split('-').reverse().join('/') : 'não informada'; }
function preparar(item, tipo) {
  let status, rascunho;
  if (tipo === 'complemento') {
    status = 'precisa_complemento';
    rascunho = 'Olá! Para continuar a consulta, preciso confirmar:\n\n' + (item.perguntas || item.pendencias).map((p,i)=>(i+1)+'. '+p).join('\n');
  } else if (tipo === 'opcoes') {
    if (!item.opcoes?.length) throw new Error('Não há opção para compor esta resposta.');
    status = 'opcao_encontrada';
    const lista = item.opcoes.map(o=>`${o.id}: ${o.origem} → ${o.destino}, de ${dataBR(o.data_ida)} a ${dataBR(o.data_volta)}, ${o.adultos} adultos, valor total fictício ${moedaBR(o.valor_total)}.`).join('\n');
    rascunho = 'Olá! No catálogo de demonstração, encontrei:\n' + lista + '\n\nEstes dados são fictícios para a atividade. Esta resposta não confirma disponibilidade real nem reserva.';
  } else if (tipo === 'sem_opcoes') {
    status = 'sem_opcao_compativel';
    rascunho = 'Olá! Não encontrei opção que atenda a todas as condições no catálogo de demonstração. Você aceita rever datas, destino ou orçamento?';
  } else throw new Error('Tipo de resposta desconhecido.');
  return {...item,status,rascunho,envio_automatico:false,revisao_necessaria:true,notificacao_enviada:false};
}
function escapar(v) { return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function apresentar(item, execucao) {
  const titulos={opcao_encontrada:'Opção encontrada',precisa_complemento:'Precisamos completar o pedido',sem_opcao_compativel:'Nenhuma opção compatível'};
  const d=item.dados; const e=escapar;
  const linhas=[['Origem',d.origem],['Destino',d.destino],['Ida',dataBR(d.data_ida)],['Volta',dataBR(d.data_volta)],['Adultos',d.adultos],['Crianças',d.criancas==null?'não informado':d.criancas],['Orçamento informado',d.orcamento_valor==null?'não informado':formatarValor(d.orcamento_valor,d.moeda)+' — '+({total:'total da viagem',por_pessoa:'por pessoa'}[d.orcamento_tipo]||'total ou por pessoa a confirmar')],['Orçamento total validado',item.orcamento_total==null?'aguardando dados':moedaBR(item.orcamento_total)]];
  const tabela=linhas.map(([k,v])=>`<tr><th>${e(k)}</th><td>${e(v??'não informado')}</td></tr>`).join('');
  const comparacao=(item.comparacao??[]).map(o=>`<tr><td>${e(o.id)}</td><td>${e(moedaBR(o.valor_total))}</td><td>${e(o.compativel?'Compatível':o.motivos.join('; '))}</td></tr>`).join('');
  const html=`<!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FIAT — ${e(titulos[item.status])}</title><style>body{font:17px/1.5 system-ui,sans-serif;background:#f3f6fa;color:#162c43;margin:0;padding:28px}main{max-width:920px;margin:auto}h1{font-size:32px;line-height:1.2}h2{font-size:22px}section{background:white;border:1px solid #d7e1eb;border-radius:14px;padding:24px;margin:18px 0}.tag{color:#146b5f;font-weight:700}table{border-collapse:collapse;width:100%;font-size:16px}td,th{text-align:left;border-bottom:1px solid #e4e9ef;padding:10px}pre{white-space:pre-wrap;font:17px/1.6 system-ui}small{color:#526476}.notice{border-left:5px solid #cf8b22;padding:12px 16px;background:#fff7e5}</style></head><body><main><span class="tag">FIAT · DEMONSTRAÇÃO DE AUTOMAÇÃO</span><h1>${e(titulos[item.status])}</h1><p class="notice">Catálogo e pedidos fictícios. Rascunho para revisão; nenhuma mensagem foi enviada.</p><section><h2>O pedido virou dados</h2><p><small>Origem dos campos: ${e(item.modo)}</small></p><table>${tabela}</table></section>${comparacao?`<section><h2>O que a consulta encontrou</h2><table><tr><th>Opção fictícia</th><th>Total</th><th>Resultado da regra</th></tr>${comparacao}</table></section>`:''}<section><h2>Resposta preparada</h2><pre>${e(item.rascunho)}</pre></section><p><small>Execução ${e(execucao??'local')}. O histórico do n8n guarda os dados desta demonstração; ele não substitui um cadastro de clientes.</small></p></main></body></html>`;
  return {...item,execucao_id:String(execucao??'local'),html};
}

return $input.all().map((x,i)=>({json:apresentar(x.json,$execution.id),pairedItem:{item:i}}));
